"""Unit tests for the cmake arguments generated by CIME.build.get_standard_cmake_args."""

from unittest import mock

import pytest

from CIME import build


def make_case(support_libs):
    """Create a mock case.

    Args:
        support_libs: Value of the CASE_SUPPORT_LIBRARIES case variable, as returned
            by ``case.get_values`` (an empty list if the variable is not defined).

    Returns:
        A mock case.
    """
    values = {
        "MODEL": "e3sm",
        "SRCROOT": "/src",
        "EXEROOT": "/exe",
        "COMP_ATM": "eam",
    }

    case = mock.MagicMock()
    case.get_value.side_effect = values.get
    case.get_values.side_effect = lambda name: (
        list(support_libs) if name == "CASE_SUPPORT_LIBRARIES" else []
    )
    case.get_build_threaded.return_value = False

    return case


@pytest.fixture(autouse=True)
def mock_build(monkeypatch):
    """Isolate get_standard_cmake_args from the config and the compset."""
    monkeypatch.setattr(build, "uses_kokkos", lambda case: True)
    monkeypatch.setattr(build, "_get_compset_comps", lambda case: ["eam", "elm"])
    monkeypatch.setattr(build.config, "common_sharedlibroot", False, raising=False)


def test_support_libraries_passed_to_cmake():
    case = make_case(["gptl", "mct", "csm_share"])

    cmake_args = build.get_standard_cmake_args(case, "shared")

    assert "-DCASE_SUPPORT_LIBRARIES='gptl;mct;csm_share'" in cmake_args


def test_support_libraries_deduplicated_keeping_order():
    case = make_case(["gptl", "mct", "gptl", "ekat", "mct"])

    cmake_args = build.get_standard_cmake_args(case, "shared")

    assert "-DCASE_SUPPORT_LIBRARIES='gptl;mct;ekat'" in cmake_args


def test_undefined_support_libraries_not_passed_to_cmake():
    case = make_case([])

    cmake_args = build.get_standard_cmake_args(case, "shared")

    assert "CASE_SUPPORT_LIBRARIES" not in cmake_args


def test_empty_support_libraries_entry_not_passed_to_cmake():
    # A variable that is defined but empty gives a list with an empty string
    case = make_case([""])

    cmake_args = build.get_standard_cmake_args(case, "shared")

    assert "CASE_SUPPORT_LIBRARIES" not in cmake_args


def test_empty_support_libraries_entries_ignored():
    case = make_case(["gptl", "", "mct"])

    cmake_args = build.get_standard_cmake_args(case, "shared")

    assert "-DCASE_SUPPORT_LIBRARIES='gptl;mct'" in cmake_args


def test_common_sharedlibroot_does_not_pass_support_libraries(monkeypatch):
    monkeypatch.setattr(build.config, "common_sharedlibroot", True, raising=False)
    case = make_case(["gptl", "mct"])

    cmake_args = build.get_standard_cmake_args(case, "shared")

    assert "CASE_SUPPORT_LIBRARIES" not in cmake_args
    assert "COMP_NAMES" not in cmake_args
    assert "USE_KOKKOS" not in cmake_args


def test_other_case_specific_arguments_still_passed():
    case = make_case(["gptl"])

    cmake_args = build.get_standard_cmake_args(case, "shared")

    assert "-DUSE_KOKKOS=TRUE" in cmake_args
    assert "-DCOMP_NAMES='eam;elm'" in cmake_args
